/**
 * 调用：worker.c/process_batch → routed_decide → 本函数
 * 返回：本函数 → routed_decide → process_batch，按 decision 处理报文
 * memset 清零 → action = 0 → DROP，枚举定义在 pipeline.h
 * 初始保留 DROP，只有后续规则允许并选出出口才设置 FORWARD
 */
memset(decision, 0, sizeof(*decision));
if (parse_status == DPPD_PARSE_MALFORMED) {
    decision->action = DPPD_PACKET_DROP;
    decision->drop_reason = DPPD_DROP_MALFORMED;
    return;
}

/* pipeline.c · 调用软件后端，单独保存规则结果 */
struct dppd_software_decision software_decision;
dppd_software_backend_decide_counted(software_backend,
    ingress_port, packet, &software_decision, counts);

/* software_backend.c · 此处 decision 指向上面的 software_decision */
memset(decision, 0, sizeof(*decision));
/* 省略空指针检查；同一规则快照供两类匹配使用，候选 0 表示未命中 */
active = atomic_load_explicit(&backend->active, memory_order_acquire);
/** ACL：支持掩码、端口范围等条件，返回候选 tag */
uint32_t tag = dppd_acl_classify(
    snapshot_acl(active, backend->capacity), ingress_port, packet);
/** exact：用完整地址和端口组合查哈希表，返回候选 tag */
uint32_t exact_tag = dppd_exact_classify(
    snapshot_exact(active, backend->capacity), ingress_port, packet);

/** 单个命中直接选用，两个都命中则按统一顺序比较 */
if (exact_tag != 0 &&
    (tag == 0 || rule_before(&active->objects[exact_tag - 1].rule,
        exact_tag, &active->objects[tag - 1].rule, tag)))
    tag = exact_tag;
if (tag != 0)
    selected = &active->objects[tag - 1];

if (selected != NULL) {
    decision->matched = true;
    for (action = 0; action < selected->rule.nb_actions; ++action) {
        const struct dppd_action *source = &selected->rule.actions[action];
        if (source->type == DPPD_ACTION_DROP)
            decision->drop = true;
        /* 省略 MARK、共享 COUNT 分支 */
        else if (source->type == DPPD_ACTION_COUNT && !packet->neighbor_retry)
            count_packet(selected->metrics, packet->packet_len, batch);
    }
}

/**
 * 软件规则 → software_decision；drop 为真时将最终 decision 设为 DROP/POLICY
 * 本例 IPv4 返回路径：本函数 → worker.c/routed_decide → process_batch
 *   → 更新丢弃统计 → 释放当前 mbuf → continue 下一个包
 * 未丢弃时携带 MARK 继续选出口；COUNT 按命中累计，后续失败不撤销
 */
dppd_software_backend_decide_counted(software_backend,
    ingress_port, packet, &software_decision, counts);
if (software_decision.drop) {
    decision->action = DPPD_PACKET_DROP;
    decision->drop_reason = DPPD_DROP_POLICY;
    return;
}
decision->has_mark = software_decision.has_mark;
decision->mark_id = software_decision.mark_id;
/* 不丢弃时继续后面的路由或端口配对，见 1.4 */
